"use server";

import { redirect } from "next/navigation";
import { validateAdminCredentials } from "@/lib/cms/admin-config";
import { clearAdminSession, setAdminSession } from "@/lib/cms/admin-session";

export async function loginAdmin(formData: FormData): Promise<void> {
  const username = String(formData.get("username") ?? "").trim();
  const password = [REDACTED]"password") ?? "");

  if (!validateAdminCredentials(username, password)) {
    redirect("/admin/login?error=1");
  }

  await setAdminSession();
  redirect("/admin/posts");
}

export async function logoutAdmin(): Promise<void> {
  await clearAdminSession();
  redirect("/admin/login");
}

export const metadata = { title: "Administração" };

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  return <div data-cms-admin="true" style={{ minHeight: "60vh" }}>{children}</div>;
}

import { redirect } from "next/navigation";
import { loginAdmin } from "../actions";
import { hasValidAdminSession } from "@/lib/cms/admin-session";

type LoginPageProps = {
  searchParams: Promise<{ error?: string }>;
};

export default async function AdminLoginPage({ searchParams }: LoginPageProps) {
  if (await hasValidAdminSession()) {
    redirect("/admin/posts");
  }

  const { error } = await searchParams;

  return (
    <section
      aria-labelledby="cms-login-title"
      style={{ maxWidth: 420, margin: "48px auto", padding: 24, background: "#fff", borderRadius: 12 }}
    >
      <h1 id="cms-login-title">Acesso administrativo</h1>
      <p>Entre para acessar o CMS da Plataforma Editorial.</p>
      {error === "1" ? (
        <p role="alert">Não foi possível autenticar com as credenciais informadas.</p>
      ) : null}
      <form action={loginAdmin} style={{ display: "grid", gap: 16 }}>
        <label>
          Usuário
          <input name="username" autoComplete="username" required style={{ display: "block", width: "100%", padding: 10 }} />
        </label>
        <label>
          Senha
          <input name="password" type="password" autoComplete="current-password" required style={{ display: "block", width: "100%", padding: 10 }} />
        </label>
        <button type="submit" style={{ padding: 12, cursor: "pointer" }}>Entrar</button>
      </form>
    </section>
  );
}

import { redirect } from "next/navigation";
import { hasValidAdminSession } from "@/lib/cms/admin-session";

export default async function AdminPage() {
  if (!(await hasValidAdminSession())) {
    redirect("/admin/login");
  }

  redirect("/admin/posts");
}

import { notFound, redirect } from "next/navigation";
import { hasValidAdminSession } from "@/lib/cms/admin-session";
import { findEditorialPostBySlug } from "@/lib/cms/editorial-catalog";

type AdminPostPageProps = {
  params: Promise<{ slug: string }>;
};

function ReadOnlyField({ label, value }: { label: string; value: string }) {
  return (
    <label style={{ display: "grid", gap: 6 }}>
      <strong>{label}</strong>
      <input value={value} readOnly aria-readonly="true" style={{ padding: 10 }} />
    </label>
  );
}

export default async function AdminPostPage({ params }: AdminPostPageProps) {
  if (!(await hasValidAdminSession())) {
    redirect("/admin/login");
  }

  const { slug } = await params;
  const post = findEditorialPostBySlug(slug);
  if (!post) notFound();

  return (
    <section aria-labelledby="cms-post-title" style={{ maxWidth: 900, margin: "48px auto", padding: 24 }}>
      <h1 id="cms-post-title">{post.title}</h1>
      <p role="status"><strong>Modo somente leitura — salvamento será disponibilizado em etapa posterior.</strong></p>

      <div style={{ display: "grid", gap: 16 }}>
        <ReadOnlyField label="Título" value={post.title} />
        <ReadOnlyField label="Descrição" value={post.description} />
        <ReadOnlyField label="Categoria" value={post.category} />
        <ReadOnlyField label="Data" value={post.date} />
        <ReadOnlyField label="Autor" value={post.author ?? ""} />
        <ReadOnlyField label="Imagem" value={post.image ?? ""} />
        <label style={{ display: "grid", gap: 6 }}>
          <strong>Conteúdo</strong>
          <textarea value={post.content} readOnly aria-readonly="true" rows={24} style={{ padding: 12, resize: "vertical" }} />
        </label>
      </div>
    </section>
  );
}

"use server";
import { redirect } from "next/navigation";
import { hasValidAdminSession } from "@/lib/cms/admin-session";
import { getCmsDatabase } from "@/lib/cms/cloudflare-context";
import { createDraft, findDraftById, updateDraft } from "@/lib/cms/draft-repository";
import { validateDraftInput, type DraftErrors } from "@/lib/cms/draft";
import { generateLocalMdx } from "@/lib/cms/local-mdx-publisher";
import { generateLocalCatalog } from "@/lib/cms/local-catalog-generator";
export type DraftActionState={errors?:DraftErrors;formError?:string};const raw=(formData:FormData)=>Object.fromEntries(formData.entries());
export async function saveNewDraft(_:DraftActionState,formData:FormData):Promise<DraftActionState>{if(!(await hasValidAdminSession()))redirect("/admin/login");const parsed=validateDraftInput(raw(formData));if(!parsed.ok)return{errors:parsed.errors};let draft;try{draft=await createDraft(getCmsDatabase(),parsed.value);}catch(error){return{formError:error instanceof Error?error.message:"Não foi possível salvar o rascunho."};}redirect(`/admin/rascunhos/${draft.id}/editar`);}
export async function saveExistingDraft(id:string,_:DraftActionState,formData:FormData):Promise<DraftActionState>{if(!(await hasValidAdminSession()))redirect("/admin/login");const parsed=validateDraftInput(raw(formData));if(!parsed.ok)return{errors:parsed.errors};try{await updateDraft(getCmsDatabase(),id,parsed.value);}catch(error){return{formError:error instanceof Error?error.message:"Não foi possível atualizar o rascunho."};}redirect(`/admin/rascunhos/${id}/editar`);}
export async function generateLocalArticle(id:string):Promise<void>{if(!(await hasValidAdminSession()))redirect("/admin/login");let query;try{const draft=await findDraftById(getCmsDatabase(),id);if(!draft)throw new Error("Rascunho não encontrado.");const parsed=validateDraftInput(draft);if(!parsed.ok)throw new Error("O rascunho possui campos inválidos.");const result=generateLocalMdx(parsed.value);query=`mdx=success&path=${encodeURIComponent(result.relativePath)}`;}catch(error){query=`mdx=error&message=${encodeURIComponent(error instanceof Error?error.message:"Não foi possível gerar o artigo local.")}`;}redirect(`/admin/rascunhos/${id}/editar?${query}`);}
export async function generateCatalogForDraft(id:string):Promise<void>{if(!(await hasValidAdminSession()))redirect("/admin/login");let query;try{const draft=await findDraftById(getCmsDatabase(),id);if(!draft)throw new Error("Rascunho não encontrado.");const result=await generateLocalCatalog(draft.slug);query=`catalog=success&before=${result.previousCount}&after=${result.currentCount}&slug=${encodeURIComponent(result.slug)}`;}catch(error){query=`catalog=error&message=${encodeURIComponent(error instanceof Error?error.message:"Não foi possível gerar o catálogo local.")}`;}redirect(`/admin/rascunhos/${id}/editar?${query}`);}

"use client";
import { useActionState } from "react";
import { BLOG_CATEGORIES } from "@/lib/blog-categories";
import type { DraftActionState } from "./draft-actions";
import type { DraftInput } from "@/lib/cms/draft";
type Action=(state:DraftActionState,data:FormData)=>Promise<DraftActionState>;
export function DraftForm({action,initial}:{action:Action;initial?:Partial<DraftInput>}){const[state,formAction,pending]=useActionState(action,{});const field=(name:keyof DraftInput,label:string,type="text")=><label>{label}<input name={name} type={type} defaultValue={(initial?.[name] as string)??""}/>{state.errors?.[name]?<span role="alert">{state.errors[name]}</span>:null}</label>;return <form action={formAction} style={{display:"grid",gap:16}}>{state.formError?<p role="alert">{state.formError}</p>:null}{field("title","Título")}{field("slug","Slug")}{field("description","Descrição")}<label>Categoria<select name="category" defaultValue={initial?.category??""}><option value="">Selecione</option>{BLOG_CATEGORIES.map(c=><option key={c.slug} value={c.slug}>{c.label}</option>)}</select>{state.errors?.category?<span role="alert">{state.errors.category}</span>:null}</label>{field("author","Autor")}{field("image","Imagem")}<label>Conteúdo<textarea name="content" rows={20} defaultValue={initial?.content??""}/>{state.errors?.content?<span role="alert">{state.errors.content}</span>:null}</label><button type="submit" disabled={pending}>{pending?"Salvando...":"Salvar rascunho"}</button></form>}

import Link from "next/link";
import { redirect } from "next/navigation";
import { logoutAdmin } from "../actions";
import { hasValidAdminSession } from "@/lib/cms/admin-session";
import { listEditorialPosts } from "@/lib/cms/editorial-catalog";
import { getCmsDatabase } from "@/lib/cms/cloudflare-context";
import { listDrafts } from "@/lib/cms/draft-repository";
import type { DraftRecord } from "@/lib/cms/draft";
export default async function AdminPostsPage(){
  if(!(await hasValidAdminSession()))redirect("/admin/login");
  const posts=listEditorialPosts();let drafts: DraftRecord[]=[];let draftError="";
  try{drafts=await listDrafts(getCmsDatabase());}catch(error){draftError=error instanceof Error?error.message:"Rascunhos indisponíveis.";}
  return <section aria-labelledby="cms-posts-title" style={{maxWidth:1100,margin:"48px auto",padding:24}}>
    <header style={{display:"flex",justifyContent:"space-between",gap:16}}><div><h1 id="cms-posts-title">Artigos</h1><Link href="/admin/posts/novo">Novo artigo</Link></div><form action={logoutAdmin}><button type="submit">Sair</button></form></header>
    <h2>Rascunhos</h2>{draftError?<p role="status">{draftError}</p>:drafts.length?<div>{drafts.map(d=><article key={d.id}><h3>{d.title}</h3><p>{d.slug}</p><Link href={`/admin/rascunhos/${d.id}/editar`}>Editar rascunho</Link></article>)}</div>:<p>Nenhum rascunho.</p>}
    <h2>Artigos publicados</h2><p>Conteúdo público atual em modo somente leitura.</p>{posts.map(post=><article key={post.slug}><h3>{post.title}</h3><p><strong>Slug:</strong> {post.slug}</p><p><strong>Categoria:</strong> {post.category}</p><Link href={`/admin/posts/${post.slug}/editar`}>Abrir em modo somente leitura</Link></article>)}
  </section>;
}

import Image from "next/image";
import { notFound } from "next/navigation";
import { generatedPosts } from "@/lib/generated-posts";

type Props = {
  params: Promise<{ slug: string }>;
};

export async function generateStaticParams() {
  return generatedPosts.map((post) => ({
    slug: post.slug,
  }));
}

export async function generateMetadata({ params }: Props) {
  const { slug } = await params;

  const post = generatedPosts.find((item) => item.slug === slug);

  if (!post) {
    return {
      title: "Post não encontrado | Tupiniquim",
    };
  }

  return {
    title: `${post.title} | Tupiniquim`,
    description: post.description,
    openGraph: {
      title: post.title,
      description: post.description,
      images: post.image ? [post.image] : [],
      type: "article",
    },
  };
}

// ─── Safe markdown renderer ───────────────────────────────────────────────────
// All user text is HTML-escaped before being placed in the output.
// Links only allow http/https protocols to prevent javascript: XSS.

function safeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function inlineMd(text: string): string {
  const e = safeHtml(text);

  return e
    .replace(/\*\*\*(.+?)\*\*\*/g, "<strong><em>$1</em></strong>")
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/_(.+?)_/g, "<em>$1</em>")
    .replace(
      /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
      (_, label, url) =>
        `<a href="${safeHtml(url)}" rel="noopener noreferrer">${label}</a>`
    );
}

function markdownToHtml(markdown: string): string {
  const blocks = markdown.split(/\n\n+/);
  const html: string[] = [];

  for (const raw of blocks) {
    const block = raw.trim();

    if (!block) continue;

    if (block === "---") {
      html.push("<hr />");
    } else if (block.startsWith("### ")) {
      html.push(`<h3>${inlineMd(block.slice(4))}</h3>`);
    } else if (block.startsWith("## ")) {
      html.push(`<h2>${inlineMd(block.slice(3))}</h2>`);
    } else if (block.startsWith("# ")) {
      html.push(`<h1>${inlineMd(block.slice(2))}</h1>`);
    } else if (block.startsWith("> ")) {
      const inner = block
        .split("\n")
        .map((line) => inlineMd(line.replace(/^> ?/, "")))
        .join("<br />");

      html.push(`<blockquote>${inner}</blockquote>`);
    } else if (/^[-*] /m.test(block)) {
      const items = block
        .split("\n")
        .filter((line) => /^[-*] /.test(line))
        .map((line) => `<li>${inlineMd(line.replace(/^[-*] /, ""))}</li>`);

      html.push(`<ul>${items.join("")}</ul>`);
    } else {
      const lines = block.split("\n").map((line) => inlineMd(line));

      html.push(`<p>${lines.join("<br />")}</p>`);
    }
  }

  return html.join("\n");
}

