"use strict";
const STOPWORDS = new Set(["a","as","o","os","um","uma","de","da","das","do","dos","e","em","no","nos","na","nas","para","por","com","sem","que","qual","quais","como","onde","me","meu","minha","the","and","or","to","of","in","is","esta","estao","estar","fica","ficam"]);
