      id: chunk.id,
      score: Number(score.toFixed(6)),
      matchedTerms: matchedTerms.sort(),
      sourcePath: chunk.sourcePath,
      startLine: chunk.startLine,
      endLine: chunk.endLine,
      language: chunk.language,
      category: chunk.category,
      content: chunk.content
