  plan: "site-context/registry/plans/PLAN-EDITORIAL-CMS-MVP.json",
  project: "site-context/registry/projects/PROJECT-REGISTRY-TUPINIQUIM.json",
  memory: "site-context/decision-memory.json",
  rules: "site-context/registry/rules/RULESET-HARNESS-QUALITY.json",
  decisionCli: "scripts/context-engine/decision-memory.js"
};

const deliveries = [
  "MVP de Ingestao Editorial Local",
  "Entrada editorial TXT preservada em content/inbox",
  "Importador multipadrao TXT para MDX",
  "Normalizacao automatica de titulos e marcadores editoriais",
  "Backup de MDX antes da substituicao do corpo",
  "Geracao controlada do catalogo estatico",
  "Catalogo local validado com 12 artigos"
];

const task = {
  id: TASK_ID,
  title: "Materializar o MVP de Ingestao Editorial Local",
  status: "completed",
  objective: "Formalizar e preservar o pipeline local TXT para MDX como corte funcional do CMS, mantendo D1 como evolucao estrutural futura.",
  acceptanceCriteria: [
    "TXT editorial permanece preservado em content/inbox.",
    "Importador multipadrao normaliza o conteudo e cria backup antes de substituir MDX.",
    "Novos MDXs usam UTF-8 sem BOM e frontmatter obrigatorio.",
    "Catalogo derivado e gerado por scripts/generate-posts.js sem edicao manual.",
    "Doze artigos estao presentes e navegaveis no ambiente local.",
    "Testes do importador permanecem verdes.",
    "Persistencia D1 continua in_progress e fora deste corte funcional."
  ]
};

const ruleSpecs = [
  ["RULE-EDITORIAL-INGESTION-001", "Preservar a fonte editorial TXT", "editorial-source", "O TXT recebido do editor deve ser preservado em content/inbox como evidencia bruta do corte local.", "Verificar existencia e integridade do TXT antes e depois da importacao."],
  ["RULE-EDITORIAL-INGESTION-002", "Tratar MDX como projecao normalizada atual", "editorial-projection", "O MDX em content/posts e a projecao normalizada atualmente consumida pelo Blog, sem substituir a futura persistencia D1.", "Confirmar frontmatter e corpo normalizado no MDX gerado."],
  ["RULE-EDITORIAL-INGESTION-003", "Proibir edicao manual do catalogo derivado", "generated-artifact", "lib/generated-posts.ts deve ser produzido por scripts/generate-posts.js e nao editado manualmente.", "Comparar origem do arquivo e executar o gerador oficial."],
  ["RULE-EDITORIAL-INGESTION-004", "Usar UTF-8 sem BOM nos novos MDXs", "file-encoding", "Novos arquivos MDX devem ser gravados em UTF-8 sem BOM.", "Inspecionar os tres primeiros bytes e o delimitador inicial."],
  ["RULE-EDITORIAL-INGESTION-005", "Criar backup antes de substituir MDX", "editorial-safety", "Toda importacao que substitui o corpo de um MDX deve criar backup previamente.", "Bloquear aceite quando o backup fisico nao existir."],
  ["RULE-EDITORIAL-INGESTION-006", "Validar importacao antes do catalogo", "editorial-validation", "A importacao deve ser validada antes da execucao de scripts/generate-posts.js.", "Exigir codigo zero, frontmatter preservado e ausencia de marcadores editoriais remanescentes."],
  ["RULE-EDITORIAL-INGESTION-007", "Separar local Git e producao", "deployment-boundary", "Postagem local, versionamento Git e publicacao Cloudflare sao etapas distintas.", "Nao declarar producao atualizada apenas com validacao em localhost."],
  ["RULE-EDITORIAL-INGESTION-008", "Manter D1 como evolucao futura", "architecture-boundary", "O MVP local de ingestao nao substitui D1 nem autoriza dupla escrita permanente entre MDX e D1.", "Planning Registry deve manter a tarefa D1 in_progress."],
  ["RULE-EDITORIAL-INGESTION-009", "Aplicar autoria padrao Greyce", "editorial-metadata", "Nos artigos atuais a autoria padrao e Greyce, salvo instrucao explicita diferente de Arthur.", "Validar o campo author do frontmatter contra a orientacao editorial vigente."],
  ["RULE-EDITORIAL-INGESTION-010", "Reutilizar o pipeline existente", "model-guidance", "Modelos futuros devem orientar o uso do pipeline editorial existente antes de propor substituicao estrutural.", "Consulta do Context Engine deve recuperar o fluxo TXT, imagem, MDX, importador, gerador e navegador."]
];

function readJson(root, relative) {
  return JSON.parse(fs.readFileSync(path.join(root, relative), "utf8"));
}
function atomicJson(root, relative, value) {
  const target = path.join(root, relative);
  const temp = `${target}.tmp`;
  fs.writeFileSync(temp, `${JSON.stringify(value, null, 2)}\n`, "utf8");
  fs.renameSync(temp, target);
}
function backupPath(root, relative) {
  return path.join(root, relative.replace(/\.json$/u, SUFFIX));
}
function backup(root, relative) {
  const source = path.join(root, relative);
  const destination = backupPath(root, relative);
  if (fs.existsSync(destination)) throw new Error(`Backup ja existe: ${destination}`);
  fs.copyFileSync(source, destination);
  return destination;
}
function addUnique(array, value) {
  if (!array.includes(value)) array.push(value);
}
function updatePlan(plan) {
  const phase = plan.phases.find((item) => item.id === "PHASE-EDITORIAL-CMS-01-FOUNDATION");
  if (!phase) throw new Error("Fase atual do CMS nao encontrada.");
  if (!phase.tasks.some((item) => item.id === TASK_ID)) phase.tasks.push(task);
  const d1 = phase.tasks.find((item) => item.id === "TASK-EDITORIAL-CMS-01-D1-DRAFT-PERSISTENCE");
  if (!d1 || d1.status !== "in_progress") throw new Error("Tarefa D1 deixou de estar in_progress.");
  return plan;
}
function updateProject(registry) {
  const epic = registry.projects.find((item) => item.id === "EPIC-004");
  if (!epic) throw new Error("EPIC-004 nao encontrado.");
  deliveries.forEach((item) => addUnique(epic.completedDeliveries, item));
  if (epic.nextStep !== "TASK-EDITORIAL-CMS-01-D1-DRAFT-PERSISTENCE") throw new Error("nextStep do EPIC-004 divergiu da tarefa D1.");
  return registry;
}
function updateRules(registry) {
  for (const [id, title, scope, statement, verification] of ruleSpecs) {
    if (!registry.rules.some((item) => item.id === id)) {
      registry.rules.push({ id, title, status: "active", scope, statement, verification, origin: "MVP de Ingestao Editorial Local validado por Arthur", decisionRef: DECISION_ID, supersedes: [] });
    }
  }
  return registry;
}
function validateUnique(root) {
  const memory = readJson(root, files.memory);
  const plan = readJson(root, files.plan);
  const project = readJson(root, files.project);
  const rules = readJson(root, files.rules);
  const phase = plan.phases.find((item) => item.id === "PHASE-EDITORIAL-CMS-01-FOUNDATION");
  if (memory.decisions.filter((item) => item.id === DECISION_ID).length !== 1) throw new Error("Nova decisao nao foi materializada exatamente uma vez.");
  if (phase.tasks.filter((item) => item.id === TASK_ID).length !== 1) throw new Error("Nova tarefa nao foi materializada exatamente uma vez.");
  if (phase.tasks.find((item) => item.id === "TASK-EDITORIAL-CMS-01-D1-DRAFT-PERSISTENCE").status !== "in_progress") throw new Error("D1 nao permaneceu in_progress.");
  const epic = project.projects.find((item) => item.id === "EPIC-004");
  for (const item of deliveries) if (!epic.completedDeliveries.includes(item)) throw new Error(`Entrega ausente: ${item}`);
  for (const [id] of ruleSpecs) {
    const found = rules.rules.filter((item) => item.id === id);
    if (found.length !== 1 || found[0].decisionRef !== DECISION_ID) throw new Error(`Regra invalida: ${id}`);
  }
}
function runCommand(root, command, args) {
  const result = spawnSync(command, args, { cwd: root, encoding: "utf8", stdio: "pipe", shell: false });
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  if (result.status !== 0) throw new Error(`Comando falhou: ${command} ${args.join(" ")}`);
}
function materialize(root, decisionInput) {
  const required = [files.plan, files.project, files.memory, files.rules, files.decisionCli];
  for (const relative of required) if (!fs.existsSync(path.join(root, relative))) throw new Error(`Arquivo ausente: ${relative}`);
  const decision = JSON.parse(fs.readFileSync(decisionInput, "utf8"));
  if (decision.id !== DECISION_ID) throw new Error("Arquivo de decisao inesperado.");

  const backed = [files.plan, files.project, files.memory, files.rules].map((relative) => backup(root, relative));
  try {
    const memory = readJson(root, files.memory);
    if (!memory.decisions.some((item) => item.id === DECISION_ID)) {
      runCommand(root, process.execPath, [files.decisionCli, "add", decisionInput]);
    }
    atomicJson(root, files.plan, updatePlan(readJson(root, files.plan)));
    atomicJson(root, files.project, updateProject(readJson(root, files.project)));
    atomicJson(root, files.rules, updateRules(readJson(root, files.rules)));
    validateUnique(root);
    console.log("[OK] Governanca do MVP editorial materializada.");
    backed.forEach((item) => console.log(`[OK] Backup: ${item}`));
  } catch (error) {
    for (const relative of [files.plan, files.project, files.memory, files.rules]) {
      fs.copyFileSync(backupPath(root, relative), path.join(root, relative));
    }
    throw error;
  }
}

if (require.main === module) {
  try {
    const root = process.cwd();
    const input = path.resolve(process.argv[2] || "DEC-2026-EDITORIAL-CMS-LOCAL-INGESTION-MVP.json");
    materialize(root, input);
  } catch (error) {
    console.error(`[FALHA] ${error.message}`);
    process.exitCode = 1;
  }
}

module.exports = { updatePlan, updateProject, updateRules, validateUnique, materialize, DECISION_ID, TASK_ID };

"use strict";
const assert = require("node:assert/strict");
const test = require("node:test");
const { updatePlan, updateProject, updateRules, DECISION_ID, TASK_ID } = require("./materialize-editorial-mvp-governance.js");

test("adiciona tarefa e preserva D1 in_progress", () => {
  const plan = { phases: [{ id: "PHASE-EDITORIAL-CMS-01-FOUNDATION", tasks: [{ id: "TASK-EDITORIAL-CMS-01-D1-DRAFT-PERSISTENCE", status: "in_progress" }] }] };
  updatePlan(plan);
  assert.equal(plan.phases[0].tasks.filter((item) => item.id === TASK_ID).length, 1);
  assert.equal(plan.phases[0].tasks[0].status, "in_progress");
  updatePlan(plan);
  assert.equal(plan.phases[0].tasks.filter((item) => item.id === TASK_ID).length, 1);
});

test("adiciona entregas sem remover pendencias", () => {
  const registry = { projects: [{ id: "EPIC-004", completedDeliveries: ["Blog"], pendingWork: ["Persistencia editorial em D1"], nextStep: "TASK-EDITORIAL-CMS-01-D1-DRAFT-PERSISTENCE" }] };
  updateProject(registry);
  assert.ok(registry.projects[0].completedDeliveries.includes("MVP de Ingestao Editorial Local"));
  assert.deepEqual(registry.projects[0].pendingWork, ["Persistencia editorial em D1"]);
});

test("adiciona dez regras ativas ligadas a nova decisao", () => {
  const registry = { rules: [] };
  updateRules(registry);
  assert.equal(registry.rules.length, 10);
  assert.ok(registry.rules.every((item) => item.status === "active" && item.decisionRef === DECISION_ID));
  updateRules(registry);
  assert.equal(registry.rules.length, 10);
});

